import type { FileTreeIconConfig } from "@pierre/trees"
import materialIcons from "./material-icon-map.json"
import materialSprite from "./material-sprite.svg?raw"

/**
 * The row icons for both the tree and the filtered search list: Material Icon Theme (the icon theme VS Code ships)
 * supplies the file marks, their per-type colours and the plain file mark for anything it does not name.
 *
 * Both files are generated by `script/material-icons.ts`; regenerate them instead of editing by hand. The theme's own
 * per-folder-name icons never apply here, because the tree renders a folder with the disclosure chevron and the
 * plugin masks a folder mark over it (see `TREE_UNSAFE_CSS`).
 */
export const FILE_TREE_ICONS = {
  set: "none",
  spriteSheet: materialSprite,
  remap: {
    "file-tree-icon-file": { name: "mim-file", viewBox: "0 0 16 16" },
    "file-tree-icon-chevron": { name: "outline-chevron-right", width: 16, height: 16, viewBox: "0 0 16 16" },
  },
  byFileName: materialIcons.byFileName,
  byFileExtension: materialIcons.byFileExtension,
} satisfies FileTreeIconConfig
